export enum BreathingPhase {
  PREP = 'PREP',
  INHALE = 'INHALE',
  HOLD = 'HOLD',
  EXHALE = 'EXHALE',
  OUTRO = 'OUTRO',
  IDLE = 'IDLE'
}

export interface AudioState {
  isPlaying: boolean;
  currentTime: number;
  duration: number;
  phase: BreathingPhase;
  cycle: number;
}

import { GoogleGenAI, Modality } from "@google/genai";

const VOICE_NAME = 'Kore'; // Rhythmic and soft

export class TTSService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });
  }

  async generateSpeech(text: string): Promise<Uint8Array> {
    try {
      const response = await this.ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: text }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: {
            voiceConfig: {
              prebuiltVoiceConfig: { voiceName: VOICE_NAME },
            },
          },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      if (!base64Audio) throw new Error("No audio data received");

      return this.decodeBase64(base64Audio);
    } catch (error) {
      console.error("TTS Generation Error:", error);
      throw error;
    }
  }

  private decodeBase64(base64: string): Uint8Array {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  }

  async decodeToAudioBuffer(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
    const dataInt16 = new Int16Array(data.buffer);
    const numChannels = 1;
    const sampleRate = 24000;
    const frameCount = dataInt16.length / numChannels;
    const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

    for (let channel = 0; channel < numChannels; channel++) {
      const channelData = buffer.getChannelData(channel);
      for (let i = 0; i < frameCount; i++) {
        channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
      }
    }
    return buffer;
  }
}

export const ttsService = new TTSService();

import { ttsService } from './ttsService';

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private oceanSource: AudioBufferSourceNode | null = null;
  private gainNode: GainNode | null = null;
  private voiceGainNode: GainNode | null = null;
  private buffers: Map<string, AudioBuffer> = new Map();

  async init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.gainNode = this.ctx.createGain();
    this.voiceGainNode = this.ctx.createGain();

    this.gainNode.connect(this.ctx.destination);
    this.voiceGainNode.connect(this.ctx.destination);

    // Low pass filter for "sleepy" sound
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 1200;
    this.gainNode.connect(filter);
    filter.connect(this.ctx.destination);
  }

  async loadAssets(onProgress: (msg: string) => void) {
    if (!this.ctx) await this.init();

    const assets = [
      { key: 'prep', text: "Welcome to your 10-minute mindful breathing practice. Please ensure you are comfortable, either lying down or seated with a straight spine. This is the 4-7-8 technique. To make it work most effectively for deep relaxation, place the tip of your tongue gently against the ridge of tissue just behind your upper front teeth. Keep it there throughout the exercise. We will begin with one full cycle practice breath. Exhale completely through your mouth, making a gentle whooshing sound, releasing all the air from your lungs. Now, let's begin the timed cycles." },
      { key: 'inhale', text: "Inhale quietly through your nose... 1... 2... 3... 4." },
      { key: 'hold', text: "Hold the breath... 1... 2... 3... 4... 5... 6... 7." },
      { key: 'exhale', text: "Exhale through the mouth, with the whoosh sound... 1... 2... 3... 4... 5... 6... 7... 8." },
      { key: 'outro', text: "You are now completing your final guided breath... Let your breathing return to its completely natural, unguided rhythm. Take a moment to simply observe the feeling of profound stillness and deep relaxation throughout your body. Carry this sense of inner quiet with you." }
    ];

    for (const asset of assets) {
      onProgress(`Generating vocal: ${asset.key}...`);
      const audioData = await ttsService.generateSpeech(asset.text);
      const buffer = await ttsService.decodeToAudioBuffer(audioData, this.ctx!);
      this.buffers.set(asset.key, buffer);
    }

    onProgress("Preparing ambient sounds...");
    await this.generateWhiteNoise();
  }

  private async generateWhiteNoise() {
    if (!this.ctx) return;
    // Simple synthesized ocean wave (periodic volume-modulated noise)
    const bufferSize = this.ctx.sampleRate * 10;
    const buffer = this.ctx.createBuffer(1, bufferSize, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = Math.random() * 2 - 1;
    }
    this.buffers.set('ocean', buffer);
  }

  playOcean() {
    if (!this.ctx || !this.buffers.has('ocean') || !this.gainNode) return;

    this.oceanSource = this.ctx.createBufferSource();
    this.oceanSource.buffer = this.buffers.get('ocean')!;
    this.oceanSource.loop = true;

    // Wave modulation logic
    const modulator = this.ctx.createGain();
    const lfo = this.ctx.createOscillator();
    lfo.type = 'sine';
    lfo.frequency.value = 0.12; // Very slow waves

    const lfoGain = this.ctx.createGain();
    lfoGain.gain.value = 0.1; 

    lfo.connect(lfoGain);
    lfoGain.connect(modulator.gain);

    this.oceanSource.connect(modulator);
    modulator.connect(this.gainNode);

    this.gainNode.gain.setValueAtTime(0, this.ctx.currentTime);
    this.gainNode.gain.linearRampToValueAtTime(0.3, this.ctx.currentTime + 5);

    lfo.start();
    this.oceanSource.start();
  }

  playVoice(key: string) {
    if (!this.ctx || !this.buffers.has(key) || !this.voiceGainNode) return;
    const source = this.ctx.createBufferSource();
    source.buffer = this.buffers.get(key)!;
    source.connect(this.voiceGainNode);
    source.start();
    return source;
  }

  stopAll() {
    if (this.oceanSource) {
      this.gainNode?.gain.linearRampToValueAtTime(0, this.ctx!.currentTime + 2);
      setTimeout(() => this.oceanSource?.stop(), 2100);
    }
  }

  get context() { return this.ctx; }
}

export const audioEngine = new AudioEngine();

import React from 'react';
import { BreathingPhase } from '../types';

interface Props {
  phase: BreathingPhase;
}

const BreathingVisual: React.FC<Props> = ({ phase }) => {
  const getPhaseStyles = () => {
    switch (phase) {
      case BreathingPhase.INHALE:
        return { 
          scale: 'scale-[1.6]', 
          opacity: 'opacity-80', 
          label: 'Inhale', 
          color: 'bg-teal-400 shadow-[0_0_80px_-10px_rgba(45,212,191,0.6)]',
          duration: 'duration-[4000ms]'
        };
      case BreathingPhase.HOLD:
        return { 
          scale: 'scale-[1.6]', 
          opacity: 'opacity-100', 
          label: 'Hold', 
          color: 'bg-emerald-500 shadow-[0_0_100px_-10px_rgba(16,185,129,0.7)]',
          duration: 'duration-[7000ms]'
        };
      case BreathingPhase.EXHALE:
        return { 
          scale: 'scale-[0.8]', 
          opacity: 'opacity-40', 
          label: 'Exhale', 
          color: 'bg-indigo-400 shadow-[0_0_60px_-10px_rgba(129,140,248,0.4)]',
          duration: 'duration-[8000ms]'
        };
      default:
        return { 
          scale: 'scale-100', 
          opacity: 'opacity-20', 
          label: '', 
          color: 'bg-white',
          duration: 'duration-[2000ms]'
        };
    }
  };

  const styles = getPhaseStyles();

  return (
    <div className="relative flex items-center justify-center w-80 h-80">
      {/* Background Glow */}
      <div 
        className={`absolute inset-0 rounded-full blur-3xl transition-all ${styles.duration} ease-in-out ${styles.color} opacity-20`}
      />

      {/* Main Circle */}
      <div 
        className={`w-48 h-48 rounded-full transition-all ${styles.duration} ease-in-out ${styles.scale} ${styles.opacity} ${styles.color} flex items-center justify-center border border-white/20`}
      >
        <span className="text-white font-serif italic text-xl drop-shadow-md">
          {styles.label}
        </span>
      </div>

      {/* Outer Ring */}
      <div className="absolute w-64 h-64 border border-white/5 rounded-full" />
      <div className="absolute w-96 h-96 border border-white/5 rounded-full" />
    </div>
  );
};

export default BreathingVisual;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { BreathingPhase } from './types';
import { audioEngine } from './services/audioEngine';
import BreathingVisual from './components/BreathingVisual';

const TOTAL_DURATION_SEC = 600; // 10 minutes

const App: React.FC = () => {
  const [phase, setPhase] = useState<BreathingPhase>(BreathingPhase.IDLE);
  const [timeLeft, setTimeLeft] = useState(TOTAL_DURATION_SEC);
  const [isLoaded, setIsLoaded] = useState(false);
  const [loadingMsg, setLoadingMsg] = useState('Initializing ZenBreath...');
  const [cycle, setCycle] = useState(0);

  const timerRef = useRef<NodeJS.Timeout | null>(null);
  const sessionActiveRef = useRef(false);

  // Logic to handle sequence transitions
  const startSession = async () => {
    if (sessionActiveRef.current) return;

    await audioEngine.init();
    sessionActiveRef.current = true;
    audioEngine.playOcean();
    runSession();
  };

  const stopSession = () => {
    sessionActiveRef.current = false;
    setPhase(BreathingPhase.IDLE);
    audioEngine.stopAll();
    if (timerRef.current) clearInterval(timerRef.current);
    setTimeLeft(TOTAL_DURATION_SEC);
    setCycle(0);
  };

  const runSession = async () => {
    // 1. Prep Phase (approx 1:15)
    setPhase(BreathingPhase.PREP);
    audioEngine.playVoice('prep');

    // Countdown timer start
    timerRef.current = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 0) {
          stopSession();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    // Wait 75 seconds for intro
    await new Promise(r => setTimeout(r, 75000));
    if (!sessionActiveRef.current) return;

    // 2. The 4-7-8 Loop (approx 7:45)
    // 465 seconds / 19 sec cycle = ~24.4 cycles
    // We will do 24 cycles
    for (let i = 1; i <= 24; i++) {
      if (!sessionActiveRef.current) break;
      setCycle(i);

      // Inhale (4s)
      setPhase(BreathingPhase.INHALE);
      audioEngine.playVoice('inhale');
      await new Promise(r => setTimeout(r, 4000));
      if (!sessionActiveRef.current) break;

      // Hold (7s)
      setPhase(BreathingPhase.HOLD);
      audioEngine.playVoice('hold');
      await new Promise(r => setTimeout(r, 7000));
      if (!sessionActiveRef.current) break;

      // Exhale (8s)
      setPhase(BreathingPhase.EXHALE);
      audioEngine.playVoice('exhale');
      await new Promise(r => setTimeout(r, 8000));
    }

    if (!sessionActiveRef.current) return;

    // 3. Outro Phase (final 60s)
    setPhase(BreathingPhase.OUTRO);
    audioEngine.playVoice('outro');
    // The ocean waves will continue via audioEngine's stop logic or until timer hits 0
  };

  useEffect(() => {
    const load = async () => {
      try {
        await audioEngine.loadAssets((msg) => setLoadingMsg(msg));
        setIsLoaded(true);
      } catch (err) {
        setLoadingMsg("Error loading assets. Please check API key.");
      }
    };
    load();

    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
      audioEngine.stopAll();
    };
  }, []);

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#05070a] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Background Ambiance */}
      <div className="absolute inset-0 z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-teal-900/10 blur-[120px] rounded-full breathe-bg" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-900/10 blur-[120px] rounded-full breathe-bg" style={{ animationDelay: '2s' }} />
      </div>

      <div className="z-10 w-full max-w-xl flex flex-col items-center text-center space-y-12">
        {/* Header */}
        <header className="space-y-2">
          <h1 className="text-4xl md:text-5xl font-serif italic text-white tracking-tight">
            ZenBreath 4-7-8
          </h1>
          <p className="text-slate-400 font-light tracking-widest uppercase text-xs">
            A 10-Minute Guided Journey to Deep Sleep
          </p>
        </header>

        {/* Main Display */}
        <div className="relative py-12">
          {isLoaded ? (
            <BreathingVisual phase={phase} />
          ) : (
            <div className="w-80 h-80 flex flex-col items-center justify-center space-y-4">
              <div className="w-12 h-12 border-2 border-teal-500/20 border-t-teal-500 rounded-full animate-spin" />
              <p className="text-sm text-slate-500 italic animate-pulse">{loadingMsg}</p>
            </div>
          )}

          {phase !== BreathingPhase.IDLE && (
            <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 w-full">
               <p className="text-2xl font-serif text-white/80 tabular-nums">
                {formatTime(timeLeft)}
              </p>
              {cycle > 0 && phase !== BreathingPhase.OUTRO && (
                <p className="text-xs uppercase tracking-[0.2em] text-slate-500 mt-2">
                  Cycle {cycle} of 24
                </p>
              )}
            </div>
          )}
        </div>

        {/* Controls */}
        <div className="w-full flex flex-col items-center space-y-8">
          {!sessionActiveRef.current ? (
            <button
              onClick={startSession}
              disabled={!isLoaded}
              className={`group relative px-12 py-4 bg-white text-black rounded-full font-medium transition-all hover:scale-105 active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed overflow-hidden shadow-[0_0_40px_-5px_rgba(255,255,255,0.3)]`}
            >
              <span className="relative z-10">Begin Practice</span>
              <div className="absolute inset-0 bg-teal-400 opacity-0 group-hover:opacity-10 transition-opacity" />
            </button>
          ) : (
            <button
              onClick={stopSession}
              className="px-10 py-3 border border-white/10 rounded-full text-slate-400 text-sm hover:bg-white/5 hover:text-white transition-colors"
            >
              End Session
            </button>
          )}

          {/* Quick Tips */}
          {phase === BreathingPhase.IDLE && isLoaded && (
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6 text-left w-full pt-12 border-t border-white/5">
              <div className="space-y-2">
                <span className="text-teal-500 font-bold text-lg">4</span>
                <p className="text-xs text-slate-400 leading-relaxed">Inhale quietly through your nose.</p>
              </div>
              <div className="space-y-2">
                <span className="text-emerald-500 font-bold text-lg">7</span>
                <p className="text-xs text-slate-400 leading-relaxed">Hold your breath with peaceful focus.</p>
              </div>
              <div className="space-y-2">
                <span className="text-indigo-500 font-bold text-lg">8</span>
                <p className="text-xs text-slate-400 leading-relaxed">Exhale completely with a 'whoosh' sound.</p>
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Footer Instructions */}
      <footer className="absolute bottom-8 text-center w-full px-6">
        <p className="text-[10px] text-slate-600 uppercase tracking-widest max-w-md mx-auto leading-loose">
          Tip: Place the tip of your tongue behind your upper front teeth throughout the practice.
        </p>
      </footer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { BreathingPhase } from './types';
