              <div className="space-y-2">
                <span className="text-indigo-500 font-bold text-lg">8</span>
                <p className="text-xs text-slate-400 leading-relaxed">Exhale completely with a 'whoosh' sound.</p>
              </div>
            </div>
          )}
        </div>
