import React, { useState, useEffect, useRef } from 'react';
import { BreathingPhase, Language } from './types';
import { audioEngine } from './services/audioEngine';
import BreathingVisual from './components/BreathingVisual';

const App: React.FC = () => {
  const [phase, setPhase] = useState<BreathingPhase>(BreathingPhase.IDLE);
  const [durationMins, setDurationMins] = useState(5);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [language, setLanguage] = useState<Language>('en');
  const [loadingMsg, setLoadingMsg] = useState('Initializing...');
  const [cycle, setCycle] = useState(0);

  const timerRef = useRef<number | null>(null);
  const sessionActiveRef = useRef(false);

  // Load assets when language changes
  useEffect(() => {
    const load = async () => {
      setIsLoading(true);
      setIsLoaded(false);
      try {
        await audioEngine.loadAssets(language, (msg) => setLoadingMsg(msg));
        setIsLoaded(true);
      } catch (err) {
        setLoadingMsg(language === 'en' ? "Error loading voice." : "Chyba při načítání hlasu.");
      } finally {
        setIsLoading(false);
      }
    };
    load();
  }, [language]);

  const startSession = async () => {
    if (sessionActiveRef.current) return;

    await audioEngine.init();
    sessionActiveRef.current = true;
    const totalSecs = durationMins * 60;
    setTimeLeft(totalSecs);
    runSession(totalSecs);
  };

  const stopSession = () => {
    sessionActiveRef.current = false;
    setPhase(BreathingPhase.IDLE);
    audioEngine.stopAll();
    if (timerRef.current !== null) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    setCycle(0);
  };

  const runSession = async (totalSecs: number) => {
    timerRef.current = window.setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 0) {
          stopSession();
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    // Calculate number of cycles (19s each)
    const numCycles = Math.floor(totalSecs / 19);

    for (let i = 1; i <= numCycles; i++) {
      if (!sessionActiveRef.current) break;
      setCycle(i);

      // Inhale (4s)
      setPhase(BreathingPhase.INHALE);
      audioEngine.playVoice('inhale');
      await new Promise(r => setTimeout(r, 4000));
      if (!sessionActiveRef.current) break;

      // Hold (7s)
      setPhase(BreathingPhase.HOLD);
      audioEngine.playVoice('hold');
      await new Promise(r => setTimeout(r, 7000));
      if (!sessionActiveRef.current) break;

      // Exhale (8s)
      setPhase(BreathingPhase.EXHALE);
      audioEngine.playVoice('exhale');
      await new Promise(r => setTimeout(r, 8000));
    }

    if (sessionActiveRef.current) {
      setPhase(BreathingPhase.OUTRO);
      audioEngine.playVoice('outro');
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#05070a] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Background Ambiance */}
      <div className="absolute inset-0 z-0">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-teal-900/5 blur-[120px] rounded-full breathe-bg" />
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-indigo-900/5 blur-[120px] rounded-full breathe-bg" style={{ animationDelay: '2s' }} />
      </div>

      <div className="z-10 w-full max-w-xl flex flex-col items-center text-center space-y-12">
        <header className="space-y-2">
          <h1 className="text-4xl md:text-5xl font-serif italic text-white tracking-tight">
            ZenBreath
          </h1>
          <p className="text-slate-500 font-light tracking-widest uppercase text-[10px]">
            {language === 'en' ? 'Mindful 4-7-8 Breathing' : 'Vědomé dýchání 4-7-8'}
          </p>
        </header>

        {/* Display */}
        <div className="relative py-8">
          {isLoaded ? (
            <BreathingVisual phase={phase} language={language} />
          ) : (
            <div className="w-80 h-80 flex flex-col items-center justify-center space-y-4">
              <div className="w-8 h-8 border-2 border-teal-500/20 border-t-teal-500 rounded-full animate-spin" />
              <p className="text-xs text-slate-600 italic animate-pulse">{loadingMsg}</p>
            </div>
          )}

          {phase !== BreathingPhase.IDLE && (
            <div className="absolute -bottom-4 left-1/2 -translate-x-1/2 w-full">
               <p className="text-2xl font-serif text-white/80 tabular-nums">
                {formatTime(timeLeft)}
              </p>
              {cycle > 0 && phase !== BreathingPhase.OUTRO && (
                <p className="text-[10px] uppercase tracking-[0.2em] text-slate-600 mt-2">
                  {language === 'en' ? `Cycle ${cycle}` : `Cyklus ${cycle}`}
                </p>
              )}
            </div>
          )}
        </div>

        {/* Controls Panel */}
        {phase === BreathingPhase.IDLE && (
          <div className={`w-full max-w-sm space-y-10 transition-opacity duration-500 ${isLoading ? 'opacity-20' : 'opacity-100'}`}>

            {/* Language Selector */}
            <div className="flex justify-center space-x-2">
              <button 
                onClick={() => setLanguage('en')}
                className={`px-4 py-1 text-xs rounded-full border transition-all ${language === 'en' ? 'bg-white text-black border-white' : 'border-white/10 text-slate-500'}`}
              >
                English
              </button>
              <button 
                onClick={() => setLanguage('cs')}
                className={`px-4 py-1 text-xs rounded-full border transition-all ${language === 'cs' ? 'bg-white text-black border-white' : 'border-white/10 text-slate-500'}`}
              >
                Čeština
              </button>
            </div>

            {/* Duration Slider */}
            <div className="space-y-4">
              <div className="flex justify-between text-[10px] uppercase tracking-widest text-slate-500">
                <span>{language === 'en' ? 'Duration' : 'Délka'}</span>
                <span className="text-white">{durationMins} min</span>
              </div>
              <input 
                type="range" 
                min="1" 
                max="20" 
                step="1"
                value={durationMins}
                onChange={(e) => setDurationMins(parseInt(e.target.value))}
                className="w-full h-1 bg-white/10 rounded-lg appearance-none cursor-pointer accent-teal-500"
              />
            </div>

            <button
              onClick={startSession}
              disabled={!isLoaded}
              className="w-full py-4 bg-white text-black rounded-full font-medium transition-all hover:scale-[1.02] active:scale-95 disabled:opacity-20 shadow-xl"
            >
              {language === 'en' ? 'Begin Practice' : 'Začít cvičení'}
            </button>
          </div>
        )}

        {phase !== BreathingPhase.IDLE && (
          <button
            onClick={stopSession}
            className="px-8 py-2 border border-white/10 rounded-full text-slate-500 text-[10px] uppercase tracking-widest hover:bg-white/5 hover:text-white transition-all"
          >
            {language === 'en' ? 'End Session' : 'Ukončit'}
          </button>
        )}
      </div>

      <footer className="absolute bottom-8 text-center w-full px-6">
        <p className="text-[9px] text-slate-700 uppercase tracking-[0.2em] max-w-xs mx-auto">
          {language === 'en' 
            ? 'Quiet, Monotone Guidance for Deep Relaxation' 
            : 'Klidné, monotónní vedení pro hlubokou relaxaci'}
        </p>
      </footer>
    </div>
  );
};

