          scale: 1.6, 
          label: isEn ? 'Inhale' : 'Nádech', 
          color: 'bg-orange-500',
          ringOpacity: 0.15
        };
      case BreathingPhase.HOLD:
        return { 
          scale: 1.6, 
          label: isEn ? 'Hold' : 'Zadržet', 
          color: 'bg-orange-500',
          ringOpacity: 0.3
        };
      case BreathingPhase.EXHALE:
        return { 
          scale: 0.85, 
          label: isEn ? 'Exhale' : 'Výdech', 
          color: 'bg-orange-500',
          ringOpacity: 0.1
        };
      case BreathingPhase.OUTRO:
        return {
          scale: 1.0,
          label: isEn ? 'Rest' : 'Klid',
          color: 'bg-white',
          ringOpacity: 0.05
        };
      default:
        return { 
          scale: 1.0, 
          label: '', 
