      <div className="absolute w-[100%] h-[100%] border border-white/5 rounded-full animate-[spin_60s_linear_infinite]" />
      <div className="absolute w-[85%] h-[85%] border border-white/[0.02] rounded-full animate-[spin_40s_linear_infinite_reverse]" />
      <div className="absolute w-[70%] h-[70%] border border-white/[0.03] rounded-full" />

      {/* Main Breathing Circle */}
      <div 
        className="relative w-52 h-52 transition-transform duration-1000 ease-in-out flex items-center justify-center"
        style={{ transform: `scale(${config.scale})` }}
      >
        {/* Base Static Layer */}
        <div className="absolute inset-0 rounded-full bg-slate-900 border border-white/10" />

        {/* The Saturation Layer (Filling Effect) */}
        <div 
          className="absolute inset-0 rounded-full bg-orange-500 shadow-[0_0_50px_rgba(251,146,60,0.3)] transition-opacity duration-300"
          style={{ 
            opacity: phase === BreathingPhase.IDLE ? 0 : saturation,
            transform: `scale(${0.95 + (progress * 0.05)})`
          }}
        />

        {/* Content Label */}
        <div className="relative z-10 flex flex-col items-center">
          <span className="text-white font-serif italic text-2xl tracking-tight drop-shadow-md transition-all duration-500">
            {config.label}
          </span>
          {phase !== BreathingPhase.IDLE && phase !== BreathingPhase.OUTRO && (
            <div className="flex space-x-1 mt-3">
               {/* Minimalist dot indicator for progress */}
               {[...Array(4)].map((_, i) => (
                 <div 
                   key={i} 
                   className={`h-1 rounded-full transition-all duration-500 ${progress > (i/4) ? 'bg-white w-3' : 'bg-white/20 w-1'}`} 
                 />
               ))}
            </div>
          )}
        </div>
      </div>

      {/* Outer Progress Ring */}
      <svg className="absolute w-full h-full -rotate-90 pointer-events-none opacity-20" viewBox="0 0 100 100">
        <circle
          cx="50" cy="50" r="48"
          fill="none"
          stroke="currentColor"
          strokeWidth="0.5"
          strokeDasharray="301.59"
          strokeDashoffset={301.59 - (progress * 301.59)}
          className={`text-white transition-all duration-100 ease-linear ${phase === BreathingPhase.IDLE ? 'opacity-0' : 'opacity-100'}`}
        />
      </svg>
    </div>
  );
};

