import { ttsService } from './ttsService';
import { Language } from '../types';

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private voiceGainNode: GainNode | null = null;
  private currentSource: AudioBufferSourceNode | null = null;
  private buffers: Map<string, AudioBuffer> = new Map();

  async init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.voiceGainNode = this.ctx.createGain();
    this.voiceGainNode.connect(this.ctx.destination);

    // Low pass for voice to make it "closer" and softer
    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 3000; 
    this.voiceGainNode.connect(filter);
    filter.connect(this.ctx.destination);
  }

  async loadAssets(lang: Language, onProgress: (msg: string) => void) {
    if (!this.ctx) await this.init();

    const isEn = lang === 'en';
    const assets = [
      { 
        key: 'inhale', 
        text: isEn ? "Inhale... 1... 2... 3... 4." : "Nádech... jedna... dva... tři... čtyři." 
      },
      { 
        key: 'hold', 
        text: isEn ? "Hold... 1... 2... 3... 4... 5... 6... 7." : "Zadržet... jedna... dva... tři... čtyři... pět... šest... sedm." 
      },
      { 
        key: 'exhale', 
        text: isEn ? "Exhale... 1... 2... 3... 4... 5... 6... 7... 8." : "Výdech... jedna... dva... tři... čtyři... pět... šest... sedm... osm." 
      },
      { 
        key: 'outro', 
        text: isEn ? "Practice complete. Rest now." : "Cvičení je hotové. Odpočívejte." 
      }
    ];

    onProgress(isEn ? "Fine-tuning voice..." : "Ladění hlasu...");
    this.buffers.clear();

    for (const asset of assets) {
      const audioData = await ttsService.generateSpeech(asset.text);
      const buffer = await ttsService.decodeToAudioBuffer(audioData, this.ctx!);
      this.buffers.set(asset.key, buffer);
    }
  }

  async playVoice(key: string): Promise<void> {
    if (!this.ctx || !this.buffers.has(key) || !this.voiceGainNode) return;

    // Force stop any currently playing voice immediately
    this.stopAll();

    return new Promise((resolve) => {
      const source = this.ctx!.createBufferSource();
      source.buffer = this.buffers.get(key)!;
      source.connect(this.voiceGainNode!);

      source.onended = () => {
        if (this.currentSource === source) {
          this.currentSource = null;
        }
        resolve();
      };

      this.currentSource = source;
      source.start();
    });
  }

  getBufferDuration(key: string): number {
    return this.buffers.get(key)?.duration || 0;
  }

  stopAll() {
    if (this.currentSource) {
      try {
        this.currentSource.onended = null; // Remove listener before stopping
        this.currentSource.stop();
      } catch (e) {
        // Source might be finished already
      }
      this.currentSource = null;
    }
  }

  get context() { return this.ctx; }
}

export const audioEngine = new AudioEngine();

import React, { useState, useEffect, useRef } from 'react';
import { BreathingPhase, Language } from './types';
import { audioEngine } from './services/audioEngine';
import BreathingVisual from './components/BreathingVisual';

const App: React.FC = () => {
  const [phase, setPhase] = useState<BreathingPhase>(BreathingPhase.IDLE);
  const [durationMins, setDurationMins] = useState(5);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [language, setLanguage] = useState<Language>('en');
  const [loadingMsg, setLoadingMsg] = useState('Initializing...');
  const [cycle, setCycle] = useState(0);
  const [progress, setProgress] = useState(0); // 0.0 to 1.0

  const timerRef = useRef<number | null>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const sessionActiveRef = useRef(false);

  // Load assets when language changes
  useEffect(() => {
    const load = async () => {
      // If we change language while playing, stop everything
      if (sessionActiveRef.current) {
        stopSession();
      }

      setIsLoading(true);
      setIsLoaded(false);
      try {
        await audioEngine.loadAssets(language, (msg) => setLoadingMsg(msg));
        setIsLoaded(true);
      } catch (err) {
        setLoadingMsg(language === 'en' ? "Error loading voice." : "Chyba při načítání hlasu.");
      } finally {
        setIsLoading(false);
      }
    };
    load();

    return () => {
      stopSession();
    };
  }, [language]);

  const startSession = async () => {
    if (sessionActiveRef.current) return;

    await audioEngine.init();
    sessionActiveRef.current = true;
    const totalSecs = durationMins * 60;
    setTimeLeft(totalSecs);
    runSession(totalSecs);
  };

  const stopSession = () => {
    sessionActiveRef.current = false;
    setPhase(BreathingPhase.IDLE);
    audioEngine.stopAll();

    if (timerRef.current !== null) {
      window.clearInterval(timerRef.current);
      timerRef.current = null;
    }
    if (progressIntervalRef.current !== null) {
      window.clearInterval(progressIntervalRef.current);
      progressIntervalRef.current = null;
    }

    setCycle(0);
    setProgress(0);
  };

  const runPhase = async (p: BreathingPhase, voiceKey: string) => {
    if (!sessionActiveRef.current) return;

    setPhase(p);
    setProgress(0);

    const bufferDuration = audioEngine.getBufferDuration(voiceKey);
    // If buffer isn't loaded yet (shouldn't happen due to isLoaded), fallback to 1s
    const durationMs = (bufferDuration || 1) * 1000;
    const startTime = Date.now();

    // Clear any leftover interval before starting a new one
    if (progressIntervalRef.current) {
      window.clearInterval(progressIntervalRef.current);
    }

    // Start playback and wait for completion
    const voicePromise = audioEngine.playVoice(voiceKey);

    return new Promise<void>((resolve) => {
      const interval = window.setInterval(() => {
        if (!sessionActiveRef.current) {
          window.clearInterval(interval);
          resolve();
          return;
        }

        const elapsed = Date.now() - startTime;
        const currentProgress = Math.min(elapsed / durationMs, 1);
        setProgress(currentProgress);
      }, 30);

      progressIntervalRef.current = interval;

      voicePromise.then(() => {
        if (progressIntervalRef.current === interval) {
          window.clearInterval(interval);
          progressIntervalRef.current = null;
        }
        setProgress(1);
        resolve();
      });
    });
  };

  const runSession = async (totalSecs: number) => {
    if (timerRef.current) window.clearInterval(timerRef.current);

    timerRef.current = window.setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) return 0;
        return prev - 1;
      });
    }, 1000);

    let currentCycle = 1;
    while (sessionActiveRef.current && timeLeft > 0) {
      setCycle(currentCycle);

      // 1. INHALE
      await runPhase(BreathingPhase.INHALE, 'inhale');
      if (!sessionActiveRef.current || timeLeft <= 0) break;

      // 2. HOLD
      await runPhase(BreathingPhase.HOLD, 'hold');
      if (!sessionActiveRef.current || timeLeft <= 0) break;

      // 3. EXHALE
      await runPhase(BreathingPhase.EXHALE, 'exhale');
      if (!sessionActiveRef.current || timeLeft <= 0) break;

      currentCycle++;
    }

    if (sessionActiveRef.current) {
      setPhase(BreathingPhase.OUTRO);
      setProgress(1);
      await runPhase(BreathingPhase.OUTRO, 'outro');
      stopSession();
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#05070a] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden select-none">
      {/* Background Glow */}
      <div className="absolute inset-0 z-0">
        <div 
          className="absolute top-[-10%] left-[-10%] w-[50%] h-[50%] bg-orange-900/10 blur-[120px] rounded-full breathe-bg transition-opacity duration-1000" 
          style={{ opacity: phase !== BreathingPhase.IDLE ? 0.8 : 0.2 }} 
        />
        <div 
          className="absolute bottom-[-10%] right-[-10%] w-[50%] h-[50%] bg-indigo-900/10 blur-[120px] rounded-full breathe-bg transition-opacity duration-1000" 
          style={{ animationDelay: '3s', opacity: phase !== BreathingPhase.IDLE ? 0.8 : 0.2 }} 
        />
      </div>

      <div className="z-10 w-full max-w-xl flex flex-col items-center text-center space-y-12">
        <header className="space-y-2">
          <h1 className="text-5xl md:text-6xl font-serif italic text-white tracking-tight">
            ZenBreath
          </h1>
          <p className="text-slate-500 font-light tracking-[0.3em] uppercase text-[10px]">
            {language === 'en' ? 'Deep Relaxation' : 'Hluboká relaxace'}
          </p>
        </header>

        {/* Visualizer Area */}
        <div className="relative py-8">
          {isLoaded ? (
            <BreathingVisual phase={phase} language={language} progress={progress} />
          ) : (
            <div className="w-80 h-80 flex flex-col items-center justify-center space-y-6">
              <div className="w-10 h-10 border-2 border-orange-500/20 border-t-orange-500 rounded-full animate-spin" />
              <p className="text-xs text-slate-500 italic tracking-widest uppercase animate-pulse">{loadingMsg}</p>
            </div>
          )}

          {phase !== BreathingPhase.IDLE && (
            <div className="absolute -bottom-6 left-1/2 -translate-x-1/2 w-full">
               <p className="text-3xl font-serif text-white/90 tabular-nums tracking-wider">
                {formatTime(timeLeft)}
              </p>
              {cycle > 0 && phase !== BreathingPhase.OUTRO && (
                <p className="text-[10px] uppercase tracking-[0.4em] text-orange-500/60 mt-2 font-medium">
                  {language === 'en' ? `Cycle ${cycle}` : `Cyklus ${cycle}`}
                </p>
              )}
            </div>
          )}
        </div>

        {/* Control Center */}
        {phase === BreathingPhase.IDLE && (
          <div className={`w-full max-w-sm space-y-12 transition-all duration-700 transform ${isLoading ? 'opacity-20 scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}>

            {/* Lang Toggle */}
            <div className="flex justify-center space-x-3">
              {(['en', 'cs'] as Language[]).map(lang => (
                <button 
                  key={lang}
                  onClick={() => setLanguage(lang)}
                  className={`px-6 py-2 text-[10px] uppercase tracking-[0.2em] rounded-full border transition-all duration-300 ${language === lang ? 'bg-white text-black border-white shadow-lg' : 'border-white/10 text-slate-500 hover:border-white/30'}`}
