        </div>

        {/* User Configuration UI */}
        {phase === BreathingPhase.IDLE && (
          <div className={`w-full max-w-sm space-y-14 transition-all duration-1000 transform ${isLoading ? 'opacity-10 scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}>

            {/* Minimalist Language Switcher */}
            <div className="flex justify-center space-x-4">
              {(['en', 'cs'] as Language[]).map(lang => (
                <button 
