import { ttsService } from './ttsService';
import { Language } from '../types';

export class AudioEngine {
  private ctx: AudioContext | null = null;
  private voiceGainNode: GainNode | null = null;
  private currentSource: AudioBufferSourceNode | null = null;
  private buffers: Map<string, AudioBuffer> = new Map();

  async init() {
    if (this.ctx) return;
    this.ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
    this.voiceGainNode = this.ctx.createGain();

    const filter = this.ctx.createBiquadFilter();
    filter.type = 'lowpass';
    filter.frequency.value = 2600; 

    this.voiceGainNode.connect(filter);
    filter.connect(this.ctx.destination);
  }

  async loadAssets(lang: Language, onProgress: (msg: string) => void) {
    if (!this.ctx) await this.init();

    this.stopAll();
    this.buffers.clear();

    const isEn = lang === 'en';
    const assets = [
      { 
        key: 'inhale', 
        text: isEn ? "Inhale... 1... 2... 3... 4." : "Nádech... jedna... dva... tři... čtyři." 
      },
      { 
        key: 'hold', 
        text: isEn ? "Hold... 1... 2... 3... 4... 5... 6... 7." : "Zadržet... jedna... dva... tři... čtyři... pět... šest... sedm." 
      },
      { 
        key: 'exhale', 
        text: isEn ? "Exhale... 1... 2... 3... 4... 5... 6... 7... 8." : "Výdech... jedna... dva... tři... čtyři... pět... šest... sedm... osm." 
      },
      { 
        key: 'outro', 
        text: isEn ? "The session is complete. Rest deeply." : "Cvičení je u konce. Odpočívejte." 
      }
    ];

    onProgress(isEn ? "Syncing voice..." : "Synchronizace hlasu...");

    for (const asset of assets) {
      const audioData = await ttsService.generateSpeech(asset.text);
      const buffer = await ttsService.decodeToAudioBuffer(audioData, this.ctx!);
      this.buffers.set(asset.key, buffer);
    }
  }

  async playVoice(key: string): Promise<void> {
    if (!this.ctx || !this.buffers.has(key) || !this.voiceGainNode) return;

    this.stopAll();

    return new Promise((resolve) => {
      if (!this.ctx) return resolve();

      const source = this.ctx.createBufferSource();
      source.buffer = this.buffers.get(key)!;
      source.connect(this.voiceGainNode!);

      source.onended = () => {
        if (this.currentSource === source) {
          this.currentSource = null;
        }
        resolve();
      };

      this.currentSource = source;
      source.start();
    });
  }

  getBufferDuration(key: string): number {
    return this.buffers.get(key)?.duration || 0;
  }

  stopAll() {
    if (this.currentSource) {
      try {
        this.currentSource.onended = null;
        this.currentSource.stop();
      } catch (e) {
      }
      this.currentSource = null;
    }
  }
}

export const audioEngine = new AudioEngine();

import React from 'react';
import { BreathingPhase, Language } from '../types';

interface Props {
  phase: BreathingPhase;
  language: Language;
  progress: number; // 0.0 to 1.0
}

const BreathingVisual: React.FC<Props> = ({ phase, language, progress }) => {
  const isEn = language === 'en';

  const getDynamicScale = () => {
    switch (phase) {
      case BreathingPhase.INHALE:
        if (progress < 0.25) {
          const slowPulse = Math.sin(progress * Math.PI * 4) * 0.02;
          return 1.0 + (progress * 0.2) + slowPulse;
        }
        const stage2Progress = (progress - 0.25) / 0.75;
        return 1.05 + (stage2Progress * 0.55);

      case BreathingPhase.HOLD:
        return 1.6;

      case BreathingPhase.EXHALE:
        const baseExhaleScale = 0.8 + (progress * 0.3); 
        const exhalePulse = Math.sin(progress * Math.PI * 10) * (0.02 * progress);
        return baseExhaleScale + exhalePulse;

      case BreathingPhase.OUTRO:
        return 1.0;

      default:
        return 1.0;
    }
  };

  const getGlowConfig = () => {
    const baseSaturation = 0.05 + (progress * 0.95);

    if (phase === BreathingPhase.INHALE) {
      if (progress < 0.25) {
        return {
          opacity: 0.1 + (progress * 0.3),
          glowSpread: 30 + (progress * 40),
          saturation: 1.1 + progress
        };
      }
      const stage2Progress = (progress - 0.25) / 0.75;
      return {
        opacity: 0.175 + (stage2Progress * 0.725),
        glowSpread: 70 + (stage2Progress * 70),
        saturation: 1.35 + (stage2Progress * 0.65)
      };
    }

    if (phase === BreathingPhase.EXHALE) {
      return {
        opacity: 0.15 + (progress * 0.45),
        glowSpread: 50 + (progress * 40),
        saturation: 1.1 + (progress * 0.5)
      };
    }

    return {
      opacity: phase === BreathingPhase.IDLE ? 0.01 : baseSaturation * 0.9,
      glowSpread: 80,
      saturation: 1.2 + progress * 0.8
    };
  };

  const getPhaseConfig = () => {
    switch (phase) {
      case BreathingPhase.INHALE:
        return { 
          label: isEn ? 'Inhale' : 'Nádech', 
          colorClass: 'bg-orange-500',
          glowBase: 'rgba(249, 115, 22,'
        };
      case BreathingPhase.HOLD:
        return { 
          label: isEn ? 'Hold' : 'Zadržet', 
          colorClass: 'bg-orange-600',
          glowBase: 'rgba(234, 88, 12,'
        };
      case BreathingPhase.EXHALE:
        return { 
          label: isEn ? 'Exhale' : 'Výdech', 
          colorClass: 'bg-orange-400',
          glowBase: 'rgba(251, 146, 60,'
        };
      case BreathingPhase.OUTRO:
        return {
          label: isEn ? 'Rest' : 'Klid',
          colorClass: 'bg-white',
          glowBase: 'rgba(255, 255, 255,'
        };
      default:
        return { 
          label: '', 
          colorClass: 'bg-slate-800',
          glowBase: 'rgba(0,0,0,'
        };
    }
  };

  const config = getPhaseConfig();
  const glowConfig = getGlowConfig();
  const dynamicScale = getDynamicScale();

  return (
    <div className="relative flex items-center justify-center w-96 h-96 select-none">
      <div 
        className="absolute inset-0 rounded-full blur-[140px] transition-all duration-300 ease-out bg-orange-500"
        style={{ 
          opacity: phase === BreathingPhase.IDLE ? 0.01 : glowConfig.opacity * 0.15,
          transform: `scale(${dynamicScale * 1.5})`
        }}
      />
      <div className="absolute w-[100%] h-[100%] border border-white/5 rounded-full animate-[spin_120s_linear_infinite] opacity-30" />
      <div className="absolute w-[80%] h-[80%] border border-white/[0.04] rounded-full animate-[spin_80s_linear_infinite_reverse]" />
      <div 
        className="relative w-60 h-60 flex items-center justify-center will-change-transform"
        style={{ 
          transform: `scale(${dynamicScale})`,
          transition: phase === BreathingPhase.HOLD ? 'transform 1000ms ease-in-out' : 'transform 150ms cubic-bezier(0.2, 0, 0.4, 1)' 
        }}
      >
        <div className="absolute inset-0 rounded-full border border-white/10 bg-[#080a0f] shadow-inner" />
        <div 
          className={`absolute inset-0 rounded-full transition-all duration-150 ${config.colorClass}`}
          style={{ 
            opacity: glowConfig.opacity,
            transform: `scale(${0.94 + (progress * 0.04)})`,
            boxShadow: `0 0 ${glowConfig.glowSpread}px ${config.glowBase}${glowConfig.opacity * 0.8})`,
            filter: `saturate(${glowConfig.saturation}) contrast(1.1)`
          }}
        />
        <div className="relative z-10 flex flex-col items-center">
          <span className="text-white font-serif italic text-3xl tracking-tight transition-all duration-500 drop-shadow-lg text-center">
            {config.label}
          </span>
          {phase !== BreathingPhase.IDLE && phase !== BreathingPhase.OUTRO && (
            <div className="flex space-x-1.5 mt-6">
               {[...Array(4)].map((_, i) => (
                 <div 
                   key={i} 
                   className={`h-1 rounded-full transition-all duration-500 ${progress > (i/4) ? 'bg-white w-5' : 'bg-white/10 w-2'}`} 
                 />
               ))}
            </div>
          )}
        </div>
      </div>
      <svg className="absolute w-full h-full -rotate-90 pointer-events-none opacity-40" viewBox="0 0 100 100">
        <circle
          cx="50" cy="50" r="48"
          fill="none"
          stroke="currentColor"
          strokeWidth="0.6"
          strokeDasharray="301.59"
          strokeDashoffset={301.59 - (progress * 301.59)}
          className={`text-orange-400 transition-all duration-100 ease-linear ${phase === BreathingPhase.IDLE ? 'opacity-0' : 'opacity-100'}`}
        />
      </svg>
    </div>
  );
};

export default BreathingVisual;

import React, { useState, useEffect, useRef } from 'react';
import { BreathingPhase, Language } from './types';
import { audioEngine } from './services/audioEngine';
import BreathingVisual from './components/BreathingVisual';

interface DurationSliderProps {
  value: number;
  onChange: (val: number) => void;
  language: Language;
}

const DurationSlider: React.FC<DurationSliderProps> = ({ value, onChange, language }) => {
  return (
    <div className="space-y-8 px-6 text-left">
      <div className="flex justify-between items-end">
        <span className="text-[10px] uppercase tracking-[0.4em] text-slate-500 font-bold">
          {language === 'en' ? 'Practice Time' : 'Doba cvičení'}
        </span>
        <span className="text-3xl font-serif italic text-white">{value}m</span>
      </div>
      <div className="relative group pt-1">
        <input 
          type="range" 
          min="1" 
          max="20" 
          step="1"
          value={value}
          onChange={(e) => onChange(parseInt(e.target.value))}
          className="w-full h-[3px] bg-white/5 rounded-full appearance-none cursor-pointer accent-orange-500 transition-all hover:bg-white/10"
        />
        <div className="absolute -bottom-6 left-0 w-full flex justify-between text-[9px] text-slate-800 font-bold tracking-widest uppercase">
          <span>1m</span>
          <span>10m</span>
          <span>20m</span>
        </div>
      </div>
    </div>
  );
};

const App: React.FC = () => {
  const [phase, setPhase] = useState<BreathingPhase>(BreathingPhase.IDLE);
  const [durationMins, setDurationMins] = useState(5);
  const [timeLeft, setTimeLeft] = useState(0);
  const [isLoaded, setIsLoaded] = useState(false);
  const [isLoading, setIsLoading] = useState(true);
  const [language, setLanguage] = useState<Language>('en');
  const [loadingMsg, setLoadingMsg] = useState('Initializing...');
  const [cycle, setCycle] = useState(0);
  const [progress, setProgress] = useState(0); 

  const timerRef = useRef<number | null>(null);
  const progressIntervalRef = useRef<number | null>(null);
  const sessionActiveRef = useRef(false);

  useEffect(() => {
    const load = async () => {
      if (sessionActiveRef.current) stopSession();
      setIsLoading(true);
      setIsLoaded(false);
      try {
        await audioEngine.loadAssets(language, (msg) => setLoadingMsg(msg));
        setIsLoaded(true);
      } catch (err) {
        setLoadingMsg(language === 'en' ? "Error loading voice." : "Chyba při načítání hlasu.");
      } finally {
        setIsLoading(false);
      }
    };
    load();

    return () => {
      if (timerRef.current) window.clearInterval(timerRef.current);
      if (progressIntervalRef.current) window.clearInterval(progressIntervalRef.current);
      audioEngine.stopAll();
    };
  }, [language]);

  const stopSession = () => {
    sessionActiveRef.current = false;
    setPhase(BreathingPhase.IDLE);
    audioEngine.stopAll();
    if (timerRef.current !== null) { window.clearInterval(timerRef.current); timerRef.current = null; }
    if (progressIntervalRef.current !== null) { window.clearInterval(progressIntervalRef.current); progressIntervalRef.current = null; }
    setCycle(0);
    setProgress(0);
  };

  const runPhase = async (p: BreathingPhase, voiceKey: string) => {
    if (!sessionActiveRef.current) return;
    setPhase(p);
    setProgress(0);
    const bufferDuration = audioEngine.getBufferDuration(voiceKey);
    const durationMs = (bufferDuration || 1) * 1000;
    const startTime = Date.now();
    if (progressIntervalRef.current) window.clearInterval(progressIntervalRef.current);
    const voicePromise = audioEngine.playVoice(voiceKey);
    return new Promise<void>((resolve) => {
      const interval = window.setInterval(() => {
        if (!sessionActiveRef.current) { window.clearInterval(interval); resolve(); return; }
        const elapsed = Date.now() - startTime;
        const currentProgress = Math.min(elapsed / durationMs, 1);
        setProgress(currentProgress);
      }, 30);
      progressIntervalRef.current = interval;
      voicePromise.then(() => {
        if (progressIntervalRef.current === interval) { window.clearInterval(interval); progressIntervalRef.current = null; }
        setProgress(1);
        resolve();
      });
    });
  };

  const startSession = async () => {
    if (sessionActiveRef.current) return;
    await audioEngine.init();
    sessionActiveRef.current = true;
    const totalSecs = durationMins * 60;
    setTimeLeft(totalSecs);
    runSession(totalSecs);
  };

  const runSession = async (totalSecs: number) => {
    if (timerRef.current) window.clearInterval(timerRef.current);
    timerRef.current = window.setInterval(() => {
      setTimeLeft(prev => { if (prev <= 1) return 0; return prev - 1; });
    }, 1000);
    let currentCycle = 1;
    while (sessionActiveRef.current && timeLeft > 0) {
      setCycle(currentCycle);
      await runPhase(BreathingPhase.INHALE, 'inhale');
      if (!sessionActiveRef.current) break;
      await runPhase(BreathingPhase.HOLD, 'hold');
      if (!sessionActiveRef.current) break;
      await runPhase(BreathingPhase.EXHALE, 'exhale');
      if (!sessionActiveRef.current) break;
      currentCycle++;
    }
    if (sessionActiveRef.current) {
      setPhase(BreathingPhase.OUTRO);
      setProgress(1);
      await runPhase(BreathingPhase.OUTRO, 'outro');
      stopSession();
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="min-h-screen bg-[#05070a] text-slate-200 flex flex-col items-center justify-center p-6 relative overflow-hidden select-none">
      <div className="absolute inset-0 z-0">
        <div 
          className="absolute top-[-15%] left-[-15%] w-[60%] h-[60%] bg-orange-900/10 blur-[150px] rounded-full breathe-bg transition-opacity duration-1000" 
          style={{ opacity: phase !== BreathingPhase.IDLE ? 0.9 : 0.3 }} 
        />
        <div 
          className="absolute bottom-[-15%] right-[-15%] w-[60%] h-[60%] bg-indigo-900/10 blur-[150px] rounded-full breathe-bg transition-opacity duration-1000" 
          style={{ animationDelay: '3s', opacity: phase !== BreathingPhase.IDLE ? 0.9 : 0.3 }} 
        />
      </div>
      <div className="z-10 w-full max-w-xl flex flex-col items-center text-center space-y-16">
        <header className="space-y-3">
          <h1 className="text-6xl md:text-7xl font-serif italic text-white tracking-tight drop-shadow-2xl">ZenBreath</h1>
          <p className="text-slate-500 font-light tracking-[0.4em] uppercase text-[11px] opacity-80">
            {language === 'en' ? 'Sleep Preparation' : 'Příprava na spánek'}
          </p>
        </header>
        <div className="relative py-4">
          {isLoaded ? (
            <BreathingVisual phase={phase} language={language} progress={progress} />
          ) : (
            <div className="w-80 h-80 flex flex-col items-center justify-center space-y-8">
              <div className="w-12 h-12 border-[3px] border-orange-500/10 border-t-orange-500 rounded-full animate-spin" />
              <p className="text-[10px] text-slate-600 italic tracking-[0.2em] uppercase animate-pulse">{loadingMsg}</p>
            </div>
          )}
          {phase !== BreathingPhase.IDLE && (
            <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 w-full">
               <p className="text-4xl font-serif text-white/95 tabular-nums tracking-widest">{formatTime(timeLeft)}</p>
              {cycle > 0 && phase !== BreathingPhase.OUTRO && (
                <p className="text-[10px] uppercase tracking-[0.4em] text-orange-500/50 mt-3 font-semibold">
                  {language === 'en' ? `Cycle ${cycle}` : `Cyklus ${cycle}`}
                </p>
              )}
            </div>
          )}
        </div>
        {phase === BreathingPhase.IDLE && (
          <div className={`w-full max-w-sm space-y-14 transition-all duration-1000 transform ${isLoading ? 'opacity-10 scale-95 pointer-events-none' : 'opacity-100 scale-100'}`}>
            <div className="flex justify-center space-x-4">
              {(['en', 'cs'] as Language[]).map(lang => (
                <button 
                  key={lang}
                  onClick={() => setLanguage(lang)}
                  className={`px-8 py-2.5 text-[10px] uppercase tracking-[0.3em] rounded-full border transition-all duration-500 ${language === lang ? 'bg-white text-black border-white shadow-[0_0_20px_rgba(255,255,255,0.2)]' : 'border-white/5 text-slate-500 hover:border-white/20 hover:text-slate-300'}`}
                >
                  {lang === 'en' ? 'English' : 'Čeština'}
                </button>
              ))}
            </div>
            <DurationSlider value={durationMins} onChange={setDurationMins} language={language} />
            <button
              onClick={startSession}
              disabled={!isLoaded}
              className="group relative w-full py-6 bg-white text-black rounded-full font-bold uppercase tracking-[0.3em] text-[11px] transition-all duration-500 hover:scale-[1.04] active:scale-95 disabled:opacity-10 shadow-[0_25px_50px_-12px_rgba(255,255,255,0.15)] overflow-hidden"
            >
              <span className="relative z-10">{language === 'en' ? 'Begin Journey' : 'Začít cestu'}</span>
              <div className="absolute inset-0 bg-orange-400 opacity-0 group-hover:opacity-20 transition-opacity duration-500" />
            </button>
          </div>
        )}
        {phase !== BreathingPhase.IDLE && (
          <button
            onClick={stopSession}
            className="px-12 py-4 border border-white/5 rounded-full text-slate-600 text-[11px] uppercase tracking-[0.4em] hover:bg-white/5 hover:text-slate-200 hover:border-white/20 transition-all duration-700"
          >
            {language === 'en' ? 'End Practice' : 'Ukončit'}
          </button>
        )}
      </div>
      <footer className="absolute bottom-12 text-center w-full px-6 opacity-30 pointer-events-none">
        <p className="text-[10px] text-slate-700 uppercase tracking-[0.5em] max-w-sm mx-auto leading-relaxed italic">
          {language === 'en' ? 'Monotone clinical guidance for neural calm' : 'Monotónní klinické vedení pro neuronální klid'}
        </p>
      </footer>
    </div>
  );
};

export default App;
